param([Parameter(Mandatory=$true)][ValidateSet('smoke','coarse','half')][string]$Window,[Parameter(Mandatory=$true)][string]$PublicStageReceipt,[string]$PriorGateReceipt,[switch]$ExecutionAuthorized)
# One matched noaux legacy u-pw OFF GPU project-main call; never prepares, decodes or queues another job.
$ErrorActionPreference='Stop';$Backend='GPU';$Window=$Window.ToLowerInvariant();$smoke=$Window -ceq 'smoke';$half=$Window -ceq 'half';$mem=$smoke -and $Backend -ceq 'GPU'
$cfg=if($smoke){'Debug'}else{'Release'}
$tests=Split-Path -Parent $PSScriptRoot;$repo=(Get-Item -LiteralPath $tests).Parent.Parent.Parent.Parent.FullName;$logs=Join-Path $tests 'logs';$src=Join-Path $repo 'src';$tag='upl_column_ringdown_off_'+$Backend+'_'+$Window+'_r1'
$folder=Join-Path $tests ('outputs\'+$tag);$record=Join-Path $logs ($tag+'.run.json');$callPath=Join-Path $logs ($tag+'.call.json');$log=Join-Path $logs ($tag+'.log')
function E([string]$p){$f=Get-Item -LiteralPath $p -Force;[ordered]@{path=$f.FullName;bytes=[long]$f.Length;sha256=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}}
function J([string]$p){[IO.File]::ReadAllText($p)|ConvertFrom-Json}
function Need([bool]$ok,[string]$why){if(!$ok){throw $why}}
function V($rows){foreach($r in $rows){Need ($r.path -and $null -ne $r.bytes -and $r.sha256) 'Missing bound Entry';$a=E $r.path;Need ($a.bytes -eq $r.bytes -and $a.sha256 -ieq $r.sha256) ('Changed bound artifact: '+$r.path)}}
function Fresh($paths){foreach($p in $paths){Need (!(Test-Path -LiteralPath $p)) ('Retained path protected: '+$p)}}
function Save([string]$p,$value){Fresh @($p);[IO.File]::WriteAllText($p,($value|ConvertTo-Json -Depth 18)+[Environment]::NewLine,(New-Object Text.UTF8Encoding($false)))}
function Owned($entry){V @($entry);$c=J $entry.path;Need ($c.owned_call_exited -and $c.typed_LASTEXITCODE_captured_immediately -and $c.exit_code -is [int] -and $c.exit_code -eq 0 -and !$c.invocation_failure) 'Owned typed exit0 required';V @($c.program,$c.log)}
function SameEntry($a,$b){return ($a.path -ieq $b.path -and $a.bytes -eq $b.bytes -and $a.sha256 -ieq $b.sha256)}
Need $ExecutionAuthorized.IsPresent 'Explicit ExecutionAuthorized required for this single Run';Fresh @($folder,$record,$callPath,$log)
$buildPath=Join-Path $logs ('upl_column_public_'+$cfg+'_r1.build.json');$buildEntry=E $buildPath;$b=J $buildPath
Need ($b.passed -and $b.configuration -ceq $cfg -and !$b.helper_built -and !$b.canonical_program_installed) 'Passed isolated authoritative project-main build required'
$bindings=@((E $PSCommandPath),(E (Join-Path $tests 'notes\upl_column_ringdown_off_run_r1.json')),$buildEntry);$sourceFreeze=$null;$adoptedCPU=$null
Need ($b.status -ceq 'full_authoritative_GPU_Rebuild_passed_no_helper_or_program_run' -and $b.source_and_protected_artifacts_unchanged -and $b.canonical_programs_unchanged -and $b.objects_exclude_main -and @($b.objects).Count -eq 110 -and @($b.runtime).Count -eq 4 -and !$b.program_or_component_run) 'Current authoritative GPU110/main build rejected'
Owned $b.project_call;$sourceFreeze=$b.source_freeze;V @($sourceFreeze);$s=J $sourceFreeze.path;$pairs=@($s.current_source_snapshot);$doc=$s.documentation_snapshot;$canonical=@($s.canonical_programs_before);$runtimeBefore=@($s.runtime_before);$program=$b.isolated_GPU_program
Need (@($s.source).Count -eq 265) 'Current GPU source265 required';$bindings+=@($sourceFreeze,$b.project_call,$b.project_main_object)+@($b.inputs)+@($s.source)
Need ($pairs.Count -eq 265 -and @($pairs.original.path|Sort-Object -Unique).Count -eq 265 -and $canonical.Count -eq 7 -and $runtimeBefore.Count -eq 4 -and $doc.original.path -and $doc.snapshot.path) 'Current265/doc/canonical7/runtime4 closure required'
foreach($row in $pairs){Need ($row.original.bytes -eq $row.snapshot.bytes -and $row.original.sha256 -ieq $row.snapshot.sha256) 'Source original/snapshot identity differs';$bindings+=@($row.original,$row.snapshot)}
$bindings+=@($doc.original,$doc.snapshot,$program)+$canonical+$runtimeBefore+@($b.objects)+@($b.tools)
$publicStage=E $PublicStageReceipt;$review=J $publicStage.path
Need ($review.stage -ceq 'upl_column_public_root_r1' -and $review.passed_implementation_review -and $review.physical_acceptance -eq $false -and @($review.primary_receipts).Count -eq 14) 'Sealed bounded public implementation root review required'
$publicProofs=@();foreach($relative in $review.primary_receipts){$proof=E (Join-Path $tests $relative);$proofJSON=J $proof.path;Need ($proofJSON.passed -eq $true) ('Public primary receipt not passed: '+$relative);$publicProofs+=@($proof)}
$bindings+=@($publicStage)+$publicProofs
$offAdmission=E (Join-Path $logs 'upl_column_ringdown_off_admission_r1.json');$offGate=J $offAdmission.path
Need ($offGate.stage -ceq 'upl_column_ringdown_off_admission_r1' -and $offGate.passed -and $offGate.physical_acceptance -eq $false -and @($offGate.inputs).Count -gt 0) 'Future explicit root OFF admission after ON half/physical review required'
V $offGate.inputs;$bindings+=@($offAdmission)+@($offGate.inputs)
$manifestPath=Join-Path $logs 'upl_column_ringdown_off_r1.inputs.json';$manifest=J $manifestPath;Need ($manifest.stage -ceq 'upl_column_ringdown_off_prepare_r1' -and $manifest.prepared -and $manifest.passed -and $manifest.physical_acceptance -eq $false -and @($manifest.jobs).Count -eq 3) 'Own prepared dyadic ringdown input manifest required'
$jobs=@($manifest.jobs|Where-Object {$_.window -ceq $Window});Need ($jobs.Count -eq 1) 'One exact ringdown window input required';$job=$jobs[0]
$steps=if($smoke){2}elseif($half){131072}else{65536};$samples=if($smoke){3}else{1277};$dt=[Math]::Pow(2,$(if($half){-20}else{-19}));$end=if($smoke){2*$dt}else{0.125};$event=5243*[Math]::Pow(2,-19);$eventStep=if($half){10486}else{5243}
Need ($job.declared_master_only_change -eq $true -and $job.dt_s -eq $dt -and $job.end_s -eq $end -and $job.steps -eq $steps -and $job.expected_samples -eq $samples) 'Declared matched master-OFF-only input/window differs'
$prefix=Join-Path (Split-Path -Parent $job.runtime.path) ([IO.Path]::GetFileNameWithoutExtension($job.runtime.path));Need ([IO.Path]::GetExtension($job.runtime.path) -ceq '.xml' -and ($prefix+'.xml') -ceq $job.runtime.path -and $prefix -ceq $job.input_prefix) 'Exact runtime XML prefix reconstruction rejected'
$bindings+=@((E $manifestPath),$job.configuration,$job.runtime,$job.initial_BI4,$job.normals)+@($manifest.inputs)+@($manifest.bindings)+@($manifest.files)
$priorGate=$null;$priorSmokeNative=$null;$priorCoarseNative=$null;$priorRun=$null
if(!$smoke){
  $priorWindow=if($half){'coarse'}else{'smoke'};$priorRun=E (Join-Path $logs ('upl_column_ringdown_off_'+$Backend+'_'+$priorWindow+'_r1.run.json'));$priorNative=E (Join-Path $logs ('upl_column_ringdown_off_'+$Backend+'_'+$priorWindow+'_r1.native.json'))
  if(!$half){Need (![string]::IsNullOrWhiteSpace($PriorGateReceipt)) 'Explicit root coarse admission required';$priorGate=E $PriorGateReceipt;$g=J $priorGate.path;Need ($g.passed -and $g.backend -ceq $Backend -and $g.window -ceq 'coarse' -and $g.physical_acceptance -eq $false -and (SameEntry $g.prior_run $priorRun) -and (SameEntry $g.native_qc $priorNative)) 'Root gate must bind own new-clock smoke Run and native check';V @($g.prior_run,$g.native_qc);V $g.inputs;$bindings+=@($priorGate)+@($g.inputs)}
  else{Need ([string]::IsNullOrWhiteSpace($PriorGateReceipt)) 'Half uses own coarse native prerequisite; no unnamed admission alias'}
  $p=J $priorRun.path;$q=J $priorNative.path;V @($q.completion);$priorDone=J $q.completion.path
  Need ($p.passed -and $p.stage -ceq 'upl_column_ringdown_off_run_r1' -and $p.backend -ceq $Backend -and $p.window -ceq $priorWindow -and $p.source_inputs_objects_runtime_canonical_unchanged -and $q.passed -and $q.backend -ceq $Backend -and $q.window -ceq $priorWindow -and $q.physical_acceptance -eq $false -and @($q.files).Count -gt 0 -and (SameEntry $q.source_run $priorRun) -and (SameEntry $p.public_stage_receipt $publicStage) -and (SameEntry $p.off_admission_receipt $offAdmission)) 'Passed own prior-window native check/source_run required'
  Need ($priorDone.passed -and $priorDone.stage -ceq 'upl_column_ringdown_off_native_r1' -and $priorDone.preset -ceq $priorWindow -and $priorDone.samples -eq $(if($half){1277}else{3}) -and $priorDone.original_typed_arrays -eq 15 -and $priorDone.native_total_arrays -eq 15 -and $priorDone.dynamic_arrays_and_global_PART_metadata_absent -and !$priorDone.native_J_n_theta_V_rho_k_PosDiv_present -and !$priorDone.physical_acceptance) 'Prior new-clock native completion required'
  if($half){Need ((SameEntry $p.source_build $buildEntry) -and (SameEntry $p.program $program)) 'Half must use own coarse current Release build/program';$priorCoarseNative=$priorNative}else{$priorSmokeNative=$priorNative;if($Backend -ceq 'GPU'){Need ($p.memcheck_executed -and $p.memcheck_zero_errors_and_leaks) 'Own new-clock GPU smoke memcheck0/0 required'}}
  Owned $p.call;Owned $q.reader_call;V $p.inputs;V $p.files;V $q.inputs;V $q.files;$bindings+=@($priorRun,$priorNative,$p.call,$q.reader_call,$q.completion)
}
V $bindings
$runtime=@();$exeDir=Split-Path -Parent $program.path
foreach($row in $b.runtime){$matchesRuntime=@($runtimeBefore|Where-Object {[IO.Path]::GetFileName($_.path) -ieq [IO.Path]::GetFileName($row.copy.path)});Need ($matchesRuntime.Count -eq 1 -and $matchesRuntime[0].bytes -eq $row.copy.bytes -and $matchesRuntime[0].sha256 -ieq $row.copy.sha256 -and (Split-Path -Parent $row.copy.path) -ieq $exeDir) 'Built GPU runtime identity/directory differs';$runtime+=@($row)}
Need ($runtime.Count -eq 4) 'Exactly four executable-directory runtime files required'
$targetArgs=@('-gpu:0');$targetArgs+=@('-stable','-mdbc_freeslip',$prefix,$folder,'-dirdataout','data','-svres',('-nsteps:'+$steps))
$tool=$program;$toolProof=$null;$argv=$targetArgs
if($mem){$toolProof=E (Join-Path $logs 'upl_gpu_perm_component_Debug_r1.call.json');$m=J $toolProof.path;Need ($m.owned_call_exited -and $m.exit_code -is [int] -and $m.exit_code -eq 0 -and $m.memcheck_zero_errors_and_leaks -and $m.program.path -ceq 'C:\Program Files\NVIDIA GPU Computing Toolkit\CUDA\v11.7\compute-sanitizer\compute-sanitizer.exe') 'Accepted CUDA11.7 memcheck program required';V @($m.program,$m.log);$tool=$m.program;$bindings+=@($toolProof,$tool,$m.log);$argv=@('--tool','memcheck','--leak-check','full','--error-exitcode','99',$program.path)+$targetArgs}
function Verify{V $bindings;V @($tool);foreach($row in $runtime){V @($row.original,$row.copy)}}
Verify
[IO.File]::WriteAllBytes($log,[byte[]]@());$started=[DateTime]::UtcNow.ToString('o');$code=$null;$launchFailure=$null;$saved=$ErrorActionPreference;Push-Location $src
try{$ErrorActionPreference='Continue';$global:LASTEXITCODE=$null;& $tool.path @argv 2>&1|Tee-Object -FilePath $log -Append|Out-Host;$code=$LASTEXITCODE}catch{$launchFailure=$_.Exception.Message}finally{Pop-Location;$ErrorActionPreference=$saved}
$text=[IO.File]::ReadAllText($log);$zero=$mem -and $text -match 'ERROR SUMMARY:\s*0 errors' -and $text -match 'LEAK SUMMARY:\s*0 bytes leaked in 0 allocations'
Save $callPath ([ordered]@{program=$tool;target_program=$program;arguments=$argv;target_arguments=$targetArgs;working_directory=$src;started_utc=$started;ended_utc=[DateTime]::UtcNow.ToString('o');direct_native_call=$true;typed_LASTEXITCODE_captured_immediately=($code -is [int]);owned_call_exited=($code -is [int]);exit_code=$code;invocation_failure=$launchFailure;log=(E $log);public_project_main=$true;fixture_or_Run_override=$false;memcheck_executed=$mem;memcheck_zero_errors_and_leaks=$zero;memcheck_tool_source=$toolProof;direct_target_call=(!$mem);target_child_exit_separately_observed=$false;physical_acceptance=$false})
# The actual typed call is immutable before inspecting or hashing any solver output.
$failure=$launchFailure;$unchanged=$false;$files=@();$rawExact=$false;$runOut=$null;$rawCount=0
try{Need ($code -is [int] -and $code -eq 0 -and !$launchFailure -and (!$mem -or $zero)) 'Owned public project-main/tool exit rejected';$runOut=E (Join-Path $folder 'Run.out');$raw=@(Get-ChildItem -LiteralPath (Join-Path $folder 'data') -File -Filter 'Part_*.bi4');$rawCount=$raw.Count;$expected=@(0..($samples-1)|ForEach-Object {'Part_{0:D4}.bi4' -f $_});$names=@($raw|ForEach-Object {$_.Name});$rawExact=($raw.Count -eq $samples -and @(Compare-Object ($names|Sort-Object) ($expected|Sort-Object)).Count -eq 0);Need $rawExact 'Native saved frame sequence/count differs; pure reader review is still required'}catch{$failure=$_.Exception.Message}
try{Verify;$unchanged=$true}catch{if(!$failure){$failure=$_.Exception.Message}}
if(Test-Path -LiteralPath $folder){$files=@(Get-ChildItem -LiteralPath $folder -File -Recurse|Sort-Object FullName|ForEach-Object {E $_.FullName})}
$passed=(!$failure -and $unchanged -and $rawExact -and $null -ne $runOut -and $code -is [int] -and $code -eq 0)
Save $record ([ordered]@{stage='upl_column_ringdown_off_run_r1';passed=[bool]$passed;backend=$Backend;window=$Window;configuration=$cfg;inputs=$bindings;source_build=$buildEntry;source_freeze=$sourceFreeze;adopted_Debug_source_build=$adoptedCPU;program=$program;input_manifest=(E $manifestPath);runtime_input=$job.runtime;input_prefix=$prefix;call=(E $callPath);arguments=$targetArgs;runtime=$runtime;canonical_programs_before=$canonical;source_snapshot=$pairs;documentation_snapshot=$doc;files=$files;run_out=$runOut;planned_steps=$steps;planned_samples=$samples;planned_dt_s=$dt;planned_end_s=$end;declared_ramp_and_drain_event_s=$event;event_completed_step_threshold=$eventStep;new_experiment_not_old_prefix=$true;matched_OFF_control_run=$true;dynamic_master_on=$false;legacy_u_pw_OFF=$true;expected_original_typed_arrays=15;expected_dynamic_arrays_and_metadata_absent=$true;native_frames=$rawCount;native_frame_sequence_exact=$rawExact;memcheck_executed=$mem;memcheck_zero_errors_and_leaks=$zero;public_stage_receipt=$publicStage;off_admission_receipt=$offAdmission;public_stage_primary_receipts=$publicProofs;prior_admission=$priorGate;prior_smoke_native=$priorSmokeNative;prior_coarse_native=$priorCoarseNative;source_inputs_objects_runtime_canonical_unchanged=$unchanged;all_raw_outputs_hash_bound=$true;public_project_main=$true;fixture_or_Run_override=$false;private_actual_complete_required=$false;solver_backend_proved_by_program_build_and_arguments=$true;native_decoder_or_QC_invoked=$false;completed_steps_or_actual_end_verified_by_this_owner=$false;force_stage_load_budget_verified=$false;independent_half_performed=$false;physical_acceptance=$false;failure=$failure})
if(!$passed){throw "OFF ringdown Run rejected; preserve $record and partial outputs, no automatic retry"};Write-Output "One OFF ringdown project-main Run sealed; pure native review remains separate: $record"
